content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: #213547;
  background-color: #f0f2f5;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  --white-key-width: 50px;
  --white-key-height: 200px;
  --black-key-width: 32px;
  --black-key-height: 120px;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem;
  max-width: 800px;
  width: 100%;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
  box-sizing: border-box;
}

.header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.header h1 {
  margin: 0 0 0.5rem 0;
  font-size: 2rem;
  color: #1a1a1a;
}

.controls {
  display: flex;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.btn {
  padding: 0.6rem 1.2rem;
  font-size: 0.95rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  background-color: #3b82f6;
  color: white;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  box-shadow: 0 4px 6px rgba(59, 130, 246, 0.2);
}

.btn:hover {
  background-color: #2563eb;
}

.btn:active {
  transform: scale(0.98);
}

.piano-wrapper {
  position: relative;
  display: flex;
  justify-content: center;
  padding: 20px;
  background: #2d3748;
  border-radius: 12px;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2), 0 8px 16px rgba(0, 0, 0, 0.1);
  overflow-x: auto;
  width: 100%;
  box-sizing: border-box;
}

.keyboard {
  position: relative;
  display: flex;
  height: var(--white-key-height);
  user-select: none;
}

.white-key {
  position: relative;
  width: var(--white-key-width);
  height: var(--white-key-height);
  background: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 0 0 6px 6px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 12px;
  cursor: pointer;
  transition: background-color 0.1s, box-shadow 0.1s;
  box-shadow: inset 0 -4px 4px rgba(0, 0, 0, 0.1);
  z-index: 1;
}

.white-key:hover {
  background: #f1f5f9;
}

.white-key.active {
  background: #cbd5e1;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2);
}

.black-key {
  position: absolute;
  width: var(--black-key-width);
  height: var(--black-key-height);
  background: #1e293b;
  border-radius: 0 0 4px 4px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 8px;
  cursor: pointer;
  transition: background-color 0.1s, box-shadow 0.1s;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3), inset 0 2px 2px rgba(255, 255, 255, 0.1);
  z-index: 2;
}

.black-key:hover {
  background: #0f172a;
}

.black-key.active {
  background: #475569;
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.3), inset 0 2px 4px rgba(0, 0, 0, 0.4);
}

.key-label {
  font-size: 0.75rem;
  font-weight: 600;
  pointer-events: none;
}

.white-key .key-label {
  color: #64748b;
}

.black-key .key-label {
  color: #94a3b8;
}

.instruction {
  margin-top: 1.5rem;
  text-align: center;
  color: #64748b;
  font-size: 0.9rem;
}

.instruction kbd {
  background-color: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  padding: 2px 6px;
  font-size: 0.8rem;
  font-family: inherit;
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.05);
  color: #475569;
}

@media (max-width: 600px) {
  :root {
    --white-key-width: 38px;
    --white-key-height: 150px;
    --black-key-width: 24px;
    --black-key-height: 90px;
  }

  .app-container {
    padding: 1rem;
  }
}

export interface NoteKey {
  note: string;
  freq: number;
  isBlack: boolean;
  label: string;
  keyName: string;
}

export interface DemoNote {
  note?: string;
  freq: number;
  delay: number;
  duration?: number;
}

export interface PianoSettings {
  volume: number;
  waveform: OscillatorType;
}

let audioCtx: AudioContext | null = null;
let masterGain: GainNode | null = null;

const getAudioContext = (): AudioContext | null => {
  try {
    if (!audioCtx) {
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (AudioContextClass) {
        audioCtx = new AudioContextClass();
      }
    }
    return audioCtx;
  } catch (e) {
    console.error('AudioContext initialization error:', e);
    return null;
  }
};

const getMasterGain = (ctx: AudioContext): GainNode => {
  if (!masterGain) {
    masterGain = ctx.createGain();
    // 複数同時発音時のクリッピング（音割れ）を防ぐため、マスターボリュームを調整
    masterGain.gain.setValueAtTime(0.4, ctx.currentTime);
    masterGain.connect(ctx.destination);
  }
  return masterGain;
};

export const playTone = (freq: number, waveform: OscillatorType = 'sine', volume: number = 0.2): void => {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;

    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const master = getMasterGain(ctx);

    osc.type = waveform;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);

    // クリックノイズ（ポップノイズ）を防ぐためのアタック・リリースエンベロープ
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0.001, now);
    gain.gain.exponentialRampToValueAtTime(Math.max(volume, 0.001), now + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 1.0);

    osc.connect(gain);
    gain.connect(master);

    osc.start(now);
    osc.stop(now + 1.0);
  } catch (e) {
    console.error('Audio playback error:', e);
  }
};

export const closeAudioContext = async (): Promise<void> => {
  if (audioCtx && audioCtx.state !== 'closed') {
    await audioCtx.close();
    audioCtx = null;
    masterGain = null;
  }
};

import { useState, useEffect, useCallback } from 'react';
import { NoteKey } from '../types';
import { playTone } from '../utils/audio';
import '../index.css';

const KEYS: NoteKey[] = [
  { note: 'C4', freq: 261.63, isBlack: false, label: 'C', keyName: 'a' },
  { note: 'Db4', freq: 277.18, isBlack: true, label: 'C#', keyName: 'w' },
  { note: 'D4', freq: 293.66, isBlack: false, label: 'D', keyName: 's' },
  { note: 'Eb4', freq: 311.13, isBlack: true, label: 'D#', keyName: 'e' },
  { note: 'E4', freq: 329.63, isBlack: false, label: 'E', keyName: 'd' },
  { note: 'F4', freq: 349.23, isBlack: false, label: 'F', keyName: 'f' },
  { note: 'Gb4', freq: 369.99, isBlack: true, label: 'F#', keyName: 't' },
  { note: 'G4', freq: 392.00, isBlack: false, label: 'G', keyName: 'g' },
  { note: 'Ab4', freq: 415.30, isBlack: true, label: 'G#', keyName: 'y' },
  { note: 'A4', freq: 440.00, isBlack: false, label: 'A', keyName: 'h' },
  { note: 'Bb4', freq: 466.16, isBlack: true, label: 'A#', keyName: 'u' },
  { note: 'B4', freq: 493.88, isBlack: false, label: 'B', keyName: 'j' },
  { note: 'C5', freq: 523.25, isBlack: false, label: 'C5', keyName: 'k' },
];

export default function Piano() {
  const [activeNotes, setActiveNotes] = useState<Record<string, boolean>>({});

  const triggerNote = useCallback((noteKey: NoteKey) => {
    playTone(noteKey.freq);
    setActiveNotes((prev) => ({ ...prev, [noteKey.note]: true }));
    setTimeout(() => {
      setActiveNotes((prev) => ({ ...prev, [noteKey.note]: false }));
    }, 300);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const found = KEYS.find((k) => k.keyName === e.key.toLowerCase());
      if (found) {
        triggerNote(found);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [triggerNote]);

  let whiteKeyCount = 0;

  return (
    <div className="piano-wrapper">
      <div className="keyboard">
        {KEYS.map((k) => {
          if (!k.isBlack) {
            whiteKeyCount++;
            return (
              <div
                key={k.note}
                className={`white-key ${activeNotes[k.note] ? 'active' : ''}`}
                onMouseDown={() => triggerNote(k)}
                onTouchStart={(e) => {
                  e.preventDefault();
                  triggerNote(k);
                }}
              >
                <span className="key-label">{k.label}</span>
                <span className="key-label" style={{ fontSize: '0.65rem', opacity: 0.7 }}>
                  [{k.keyName.toUpperCase()}]
                </span>
              </div>
            );
          } else {
            const leftPos = `calc(var(--white-key-width) * ${whiteKeyCount} - var(--black-key-width) / 2)`;
            return (
              <div
                key={k.note}
                className={`black-key ${activeNotes[k.note] ? 'active' : ''}`}
                style={{ left: leftPos }}
                onMouseDown={() => triggerNote(k)}
                onTouchStart={(e) => {
                  e.preventDefault();
                  triggerNote(k);
                }}
              >
                <span className="key-label">{k.label}</span>
                <span className="key-label" style={{ fontSize: '0.6rem', opacity: 0.7 }}>
                  [{k.keyName.toUpperCase()}]
                </span>
              </div>
            );
          }
        })}
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import Piano from './components/Piano';
import { DEMO_NOTES } from './demoData';
import './index.css';

export default function App() {
  const [isPlayingDemo, setIsPlayingDemo] = useState(false);
  const timersRef = useRef<NodeJS.Timeout[]>([]);

  const playDemo = () => {
    if (isPlayingDemo) return;
    setIsPlayingDemo(true);

    timersRef.current.forEach((t) => clearTimeout(t));
    timersRef.current = [];

    DEMO_NOTES.forEach((note) => {
      const timer = setTimeout(() => {
        window.dispatchEvent(new KeyboardEvent('keydown', { key: note.keyName }));
      }, note.delay);
      timersRef.current.push(timer);
    });

    const endTimer = setTimeout(() => {
      setIsPlayingDemo(false);
    }, 2500);
    timersRef.current.push(endTimer);
  };

  useEffect(() => {
    return () => {
      timersRef.current.forEach((t) => clearTimeout(t));
    };
  }, []);

  return (
    <div className="app-container">
      <div className="header">
        <h1>バーチャルピアノ</h1>
        <p style={{ color: '#64748b', margin: 0 }}>1オクターブ（C4〜C5）の鍵盤演奏アプリ</p>
      </div>

      <div className="controls">
        <button className="btn" onClick={playDemo} disabled={isPlayingDemo}>
          {isPlayingDemo ? '演奏中...' : 'デモ演奏を聴く'}
        </button>
      </div>

      <Piano />

      <div className="instruction">
        マウス・タッチ操作のほか、キーボードの <kbd>A</kbd> 〜 <kbd>K</kbd> キー（黒鍵は <kbd>W</kbd>, <kbd>E</kbd> など）でも演奏できます。
      </div>
    </div>
  );
}

